int x = 5;

++x; // Increment x by 1
printf("%d\n", x); // 6

// ─────────────────────────────────────

int x = 5;

--x; // Decrement x by 1
printf("%d\n", x); // 4

// ─────────────────────────────────────

int x = 5;

++x; // Increment x by 1 (x becomes 6)
--x; // Decrement x by 1 (x becomes 5 again)

printf("%d\n", x); // 5

